<?php use VazinCMS\Security; ?><section class="title"><div><h1>گزارش مالی</h1><p>خلاصه فاکتورها و آخرین پرداخت‌های قطعی</p></div></section><section class="grid"><?php foreach($summary as $s):?><article class="panel"><h2><?=Security::e($s['currency'])?></h2><dl><dt>کل فاکتورها</dt><dd><?=Security::e($s['invoiced'])?></dd><dt>فاکتورهای تسویه‌شده</dt><dd><?=Security::e($s['paid_invoices'])?></dd><dt>بدهی باز</dt><dd><?=Security::e($s['open_total'])?></dd></dl></article><?php endforeach;?></section><section class="panel"><h2>آخرین پرداخت‌ها</h2><div class="table-wrap"><table><thead><tr><th>تاریخ</th><th>فاکتور</th><th>مشتری</th><th>مبلغ</th><th>روش</th><th>شناسه</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=Security::e($p['created_at'])?></td><td><a href="/admin/invoices/<?=$p['invoice_id']?>"><?=Security::e($p['invoice_number'])?></a></td><td><?=Security::e($p['customer'])?></td><td><?=Security::e($p['amount'].' '.$p['currency'])?></td><td><?=Security::e($p['method'])?></td><td><?=Security::e((string)$p['reference'])?></td></tr><?php endforeach;?></tbody></table></div></section>
